steps.template:
`VXLAN Fabric Change - IPAM Allocation Successful`
IAP Job Link: <https://44.209.81.98:3443/operations-manager/#/jobs/cc8cd90384484d8998d5c3b2${jobID}|IAP-Job-Status>
Server Subnet: ${serverSubnet}
Anycast GW IP: ${anycastGWIP}
VLAN Number: ${accessVlan}

document.template:
config
vlan {{ overlayVRFVlan }}
 vn-segment {{ l3VNID }}
interface vlan{{ overlayVRFVlan }}
 no shutdown
 vrf member vxlan-{{ l3VNID }}
 ip forward
 no ip redirects
vlan {{ accessVlan }}
 vn-segment {{ l2VNID }}
vrf context vxlan-{{ l3VNID }}
 vni {{ l3VNID }}
 rd auto
 address-family ipv4 unicast
  route-target both auto
  route-target both auto evpn
interface vlan{{ accessVlan }}
 no shutdown
 vrf member vxlan-{{ l3VNID }}
 ip address {{ anycastGWIP }} tag 54321
 fabric forwarding mode anycast-gateway
interface nve1
 no shutdown
 source-interface loopback1
 host-reachability protocol bgp
 member vni {{ l3VNID }} associate-vrf
 member vni {{ l2VNID }}
 mcast-group 239.0.0.1
{% for interface in interfaces %}
interface {{ interface }}
 switchport
 switchport access vlan {{ accessVlan }}
{% endfor %}
router bgp 65535
 vrf vxlan-{{ l3VNID }}
  address-family ipv4 unicast
   redistribute direct route-map HOST-SVI
end
copy run start

config
{% for interface in interfaces %}
default interface {{ interface }}
{% endfor %}
router bgp 65535
 no vrf vxlan-{{ l3VNID }}
interface nve1
 no member vni {{ l3VNID }} associate-vrf
 no member vni {{ l2VNID }}
no interface vlan{{ accessVlan }}
no interface vlan{{ overlayVRFVlan }}
no vlan {{ overlayVRFVlan }}
no vlan {{ accessVlan }}
no vrf context vxlan-{{ l3VNID }}
end
